questionvariables.text:
scenario : rand(4);
featuretext : if scenario=0 then "Its graph is a straight line with a constant rate of change."
              elseif scenario=1 then "Its graph has exactly one turning point and is symmetric about a vertical line through that point."
              elseif scenario=2 then "Its graph has exactly one point of inflection, can have up to two turning points, and its two ends go in opposite directions."
              else "Its graph gets closer and closer to a horizontal line (an asymptote) on one side without reaching it, and becomes steeper and steeper on the other side.";
ta : if scenario=0 then "linear" elseif scenario=1 then "quadratic" elseif scenario=2 then "cubic" else "exponential";
/* Booleans wrapped in is() so each option carries true or false, not an unevaluated equation */
opts : [["linear", is(scenario=0), "Linear"],["quadratic", is(scenario=1), "Quadratic"],["cubic", is(scenario=2), "Cubic"],["exponential", is(scenario=3), "Exponential"]];
